def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'D'
    if n == 2:
        return 'C'
    if n == 3:
        return 'D'
    if n == 4:
        return 'C'

    def default_retaliator(hist):
        m = len(hist)
        if m >= 90:
            return 'D'
        last_me, last_opp = hist[-1]
        if last_opp == 'D':
            return 'D'
        if m >= 20 and m % 5 == 0:
            return 'D'
        return 'C'

    def default_slot6(hist, rng):
        m = len(hist)
        opp_D = sum(1 for a, b in hist if b == 'D')
        last_me, last_opp = hist[-1]
        if m >= 90:
            return 'D'
        if last_opp == 'D':
            if opp_D <= m * 0.1:
                return 'C' if rng.random() < 0.5 else 'D'
            return 'D'
        if m >= 20 and m % 10 == 0:
            return 'D'
        return 'C'

    def high_exploit(hist):
        if hist[-1][0] == 'C':
            return 'D'
        else:
            return 'C'

    if history[2][1] == 'D':
        return default_retaliator(history)
    else:
        if history[4][1] == 'C':
            return high_exploit(history)
        else:
            if n == 5:
                return 'C'
            if n == 6:
                return 'C'
            if n == 7:
                return 'C'
            if n == 8:
                return 'C'
            if n == 9:
                return 'C'
            if n == 10:
                return 'D'
            if n == 11:
                return 'C'
            if n >= 12:
                if history[11][1] == 'C':
                    return high_exploit(history)
                else:
                    return default_slot6(history, rng)
